  let aS1=0, iS1=0, aS2=0, iS2=0;
  for (const [sX, sY, f, sp, wt] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS1 += Math.sin(d*f - t*sp)*wt;
    iS1 += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5)*wt;
